-- Versão Otimizada da VIEW BigQuery
CREATE OR REPLACE VIEW `br-ist-ve-hubgrade.00003_hubgrade_views_operacionais.00003_067_ve_brusque_indicadores_consolidado` AS

WITH month_mapping AS (
  SELECT 
    mes_texto,
    mes_data
  FROM UNNEST([
    STRUCT('JANEIRO' AS mes_texto, DATE '2024-01-01' AS mes_data),
    STRUCT('FEVEREIRO', DATE '2024-02-01'),
    STRUCT('MARÇO', DATE '2024-03-01'),
    STRUCT('ABRIL', DATE '2024-04-01'),
    STRUCT('MAIO', DATE '2024-05-01'),
    STRUCT('JUNHO', DATE '2024-06-01'),
    STRUCT('JULHO', DATE '2024-07-01'),
    STRUCT('AGOSTO', DATE '2024-08-01'),
    STRUCT('SETEMBRO', DATE '2024-09-01'),
    STRUCT('OUTUBRO', DATE '2024-10-01'),
    STRUCT('NOVEMBRO', DATE '2024-11-01'),
    STRUCT('DEZEMBRO', DATE '2024-12-01')
  ])
),

-- Função para limpar e converter strings para números
cleaned_data AS (
  SELECT 
    *,
    -- Função auxiliar para limpeza de strings
    UPPER(TRIM(SESMT_MES)) AS mes_limpo
  FROM `br-ist-ve-hubgrade.00002_hubgrade_tabelas_operacionais.00002_067_ve_brusque_indicadores_consolidado`
)

SELECT
  -- Mapeamento otimizado de mês usando JOIN
  mm.mes_data AS MES,
  
  -- Função UDF para conversão otimizada (substitui múltiplos REPLACE)
  SAFE_CAST(
    REGEXP_REPLACE(
      REGEXP_REPLACE(
        REGEXP_REPLACE(TRIM(COALESCE(SESMT_META_A_M, '0')), r'[,%-]', '.'),
        r'[^0-9.]', ''
      ),
      r'\.+', '.'
    ) AS FLOAT64
  ) AS SESMT_META_A_M,
  
  -- Aplicando a mesma lógica otimizada para todos os campos
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_VISITAS_DE_SEGURANCA, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_VISITAS_DE_SEGURANCA,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_VISITADOS, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_VISITADOS,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_SESMT, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_SESMT,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_RH, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_RH,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_BIOGAS, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_BIOGAS,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_MANUTENCAO, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_MANUTENCAO,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_ETE, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_ETE,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_OPA, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_OPA,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_ADM, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_ADM,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_UTM, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_UTM,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_BALANCA, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_BALANCA,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_TRANSBORDO, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_TRANSBORDO,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_CTRSS, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_CTRSS,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_TOTAL, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_TOTAL,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(SESMT_META_MENSAL, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS SESMT_META_MENSAL,
  
  -- RH Fields
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(RH_ADMISSAO, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS RH_ADMISSAO,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(RH_ATIVOS, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS RH_ATIVOS,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(RH_TEMPORARIO, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS RH_TEMPORARIO,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(RH_AFASTADOS, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS RH_AFASTADOS,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(RH_ATESTADOS, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS RH_ATESTADOS,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(RH_HORAS_EXTRAS, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS RH_HORAS_EXTRAS,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(RH_ABSENTEISMO, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS RH_ABSENTEISMO,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(RH_DEMISSOES, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS RH_DEMISSOES,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(RH_ENTREVISTAS, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS RH_ENTREVISTAS,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(RH_VAGAS, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS RH_VAGAS,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(RH_TURNOVER, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS RH_TURNOVER,
  
  -- BIOGAS Fields
