  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(BIOGAS_BIOGAS_CAPTADO, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS BIOGAS_CAPTADO,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(BIOGAS_METANO_MEDIA_LATAM_NM3_H, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS METANO_MEDIA_LATAM_NM3_H,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(BIOGAS_METANO_CAPTADO, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS METANO_CAPTADO,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(BIOGAS_METANO_MEDIA_LATAM_PERC, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS METANO_MEDIA_LATAM_PERC,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(BIOGAS_METANO_MEDIA_REALIZADO_PERC, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS METANO_MEDIA_REALIZADO_PERC,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(BIOGAS_PLANTA_VALOR_REAL_PERC, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS PLANTA_VALOR_REAL_PERC,
