  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(BIOGAS_METANO_RESIDUO_RECEBIDO, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS METANO_RESIDUO_RECEBIDO,
