  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(BIOGAS_NOVOS_POCOS, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS NOVOS_POCOS,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(BIOGAS_BIOGAS_TOTAL_NM3_ACUMULADO, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS BIOGAS_TOTAL_NM3_ACUMULADO,
  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(BIOGAS_METANO_TOTAL_NM3_ACUMULADO, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS METANO_TOTAL_NM3_ACUMULADO,
  
