  SAFE_CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(COALESCE(AUTOCLAVE_RECEBIDO, '0')), r'[,%-]', '.'), r'[^0-9.]', ''), r'\.+', '.') AS FLOAT64) AS AUTOCLAVE_RECEBIDO,
